import {gunzipSync} from "node:zlib";
import postgres from "postgres";
import {isImportTarget,importVerifiedNames} from "./scripts/name-import.mjs";
import {readFile} from "node:fs/promises";
import * as XLSX from "xlsx";
import { parse as parseCSV } from "csv-parse/sync";
import { load } from "cheerio";
import { createHash, createHmac, randomUUID, timingSafeEqual } from "node:crypto";
const env=Bun.env;
const RELEASE="praani-ember-render-v2";
const sql=postgres(env.DATABASE_URL||"",{max:5,connect_timeout:12});
const langs=["Kannada","Hindi","Tamil","Telugu","Malayalam","Marathi","Bengali","Gujarati","Punjabi","Odia","Assamese","Konkani","Tulu","Kodava","Urdu","Sanskrit","Nepali","Manipuri","Bodo","Santali","Khasi","Mizo","Sindhi","Kashmiri","Dogri","Maithili","Ladakhi","Marwari","Rajasthani","Tibetan","Other"];
const kinds=["Bird","Mammal","Snake"];
const norm=x=>String(x||"").normalize("NFKC").trim().replace(/\s+/gu," ").toLocaleLowerCase("und");
const clean=(x,max=100)=>typeof x==="string"?x.normalize("NFC").trim().replace(/\s+/gu," ").slice(0,max):"";
const sha=x=>createHash("sha256").update(x).digest("hex");
const hmac=x=>createHmac("sha256",env.SESSION_SECRET||"").update(x).digest("hex");
const now=()=>Math.floor(Date.now()/1000);
const statements=[
"CREATE TABLE IF NOT EXISTS species_catalog(id TEXT PRIMARY KEY,species_kind TEXT NOT NULL,scientific TEXT NOT NULL,common TEXT,family TEXT,alternative_names JSONB NOT NULL DEFAULT '[]',subgroup TEXT NOT NULL DEFAULT '')",
"CREATE TABLE IF NOT EXISTS local_names(id UUID PRIMARY KEY,species_id TEXT NOT NULL REFERENCES species_catalog(id),species_kind TEXT NOT NULL,name TEXT NOT NULL,name_key TEXT NOT NULL,language TEXT NOT NULL,region TEXT NOT NULL DEFAULT '',region_key TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL,UNIQUE(species_id,name_key,language,region_key))",
"CREATE TABLE IF NOT EXISTS common_suggestions(id UUID PRIMARY KEY,species_id TEXT NOT NULL REFERENCES species_catalog(id),species_kind TEXT NOT NULL,name TEXT NOT NULL,name_key TEXT NOT NULL,why TEXT NOT NULL,language TEXT NOT NULL,region TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL,UNIQUE(species_id,name_key))",
"CREATE TABLE IF NOT EXISTS votes(suggestion_id UUID NOT NULL REFERENCES common_suggestions(id) ON DELETE CASCADE,browser_hash TEXT NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(suggestion_id,browser_hash))",
"CREATE TABLE IF NOT EXISTS rate_events(ip_hash TEXT NOT NULL,action TEXT NOT NULL,created_at BIGINT NOT NULL)",
"CREATE TABLE IF NOT EXISTS local_name_sources(source_key TEXT PRIMARY KEY,local_name_id UUID NOT NULL REFERENCES local_names(id) ON DELETE CASCADE,source_name TEXT NOT NULL,source_url TEXT NOT NULL,source_locator TEXT NOT NULL,source_payload JSONB NOT NULL,import_version TEXT NOT NULL,imported_at BIGINT NOT NULL)",
"CREATE TABLE IF NOT EXISTS local_name_context(local_name_id UUID PRIMARY KEY REFERENCES local_names(id) ON DELETE CASCADE,learned_from TEXT NOT NULL,context TEXT NOT NULL DEFAULT '')",
"CREATE INDEX IF NOT EXISTS idx_name_sources_local ON local_name_sources(local_name_id)",
"CREATE INDEX IF NOT EXISTS idx_local_species ON local_names(species_id)",
"CREATE INDEX IF NOT EXISTS idx_local_recent ON local_names(created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_suggest_species ON common_suggestions(species_id)",
"CREATE INDEX IF NOT EXISTS idx_rate ON rate_events(ip_hash,action,created_at)"
];
let init;
let namesImport=null;
const ready=()=>init||(init=(async()=>{for(const s of statements)await sql.unsafe(s);if(isImportTarget(env.DATABASE_URL)){const dataset=JSON.parse(gunzipSync(await readFile(new URL("./data/verified-local-names.json.gz",import.meta.url))).toString("utf8"));namesImport=await importVerifiedNames(sql,dataset,{apply:true});console.log("Praani sourced names import",JSON.stringify(namesImport));}})().catch(e=>{init=null;throw e}));
class Err extends Error{constructor(message,status=400){super(message);this.status=status}}
const response=(o,status=200,heads={})=>new Response(JSON.stringify(o),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","x-praani-release":RELEASE,...heads}});
const page=(s,type="text/html; charset=utf-8")=>new Response(s,{headers:{"content-type":type,"x-content-type-options":"nosniff","cache-control":"no-store","x-praani-release":RELEASE}});
const validateOrigin=r=>{const origin=r.headers.get("origin");const approved=["https://praani-app-production.up.railway.app","https://praani.indiverse.live","https://praani-web.onrender.com",...(env.PUBLIC_ORIGIN?[env.PUBLIC_ORIGIN]:[])];if(origin&&!approved.includes(origin))throw new Err("Origin blocked",403);const sf=r.headers.get("sec-fetch-site");if(sf&&!["same-origin","none"].includes(sf))throw new Err("Cross-site request blocked",403)};
const body=async r=>{if(!r.headers.get("content-type")?.includes("application/json"))throw new Err("JSON required",415);const s=await r.text();if(s.length>6000)throw new Err("Submission too large",413);try{const v=JSON.parse(s);if(!v||typeof v!=="object"||Array.isArray(v))throw Error();return v;}catch{throw new Err("Invalid JSON",400)}};
const authed=r=>{const t=(r.headers.get("cookie")||"").match(/(?:^|;\s*)praani_admin=(\d{10})\.([0-9a-f]{64})/);if(!t||now()>Number(t[1]))return false;return timingSafeEqual(Buffer.from(t[2]),Buffer.from(hmac(t[1]+"|"+env.ADMIN_EMAIL)))};
const throttle=async(r,act,max,window)=>{const ip=r.headers.get("x-forwarded-for")?.split(",")[0]||r.headers.get("cf-connecting-ip")||"anonymous";const h=sha(ip+"|"+env.SESSION_SECRET+"|"+act);const z=await sql.unsafe("SELECT COUNT(*)::int AS n FROM rate_events WHERE ip_hash=$1 AND action=$2 AND created_at>$3",[h,act,now()-window]);if(z[0].n>=max)throw new Err("Too many requests, try again later",429);await sql.unsafe("INSERT INTO rate_events(ip_hash,action,created_at) VALUES($1,$2,$3)",[h,act,now()]);if(Math.random()<.02)await sql.unsafe("DELETE FROM rate_events WHERE created_at<$1",[now()-172800])};
const safeSnakeName=x=>{if(typeof x!=="string")return null;const s=x.trim().replace(/\\s+/g," ");if(!s||s.length>95||s.split(" ").length>12||/English common name not available|Synonym|Distribution|Higher Taxa|References|Etymology|Type locality|Reproduction|\\b(?:Chinese|German|French):|\\bG:|\\bE:|\\\\u[0-9a-fA-F]{4}/i.test(s))return null;return s};
const parseAliases=value=>{
 let a=value;
 if(typeof a==="string"){try{a=JSON.parse(a)}catch{return []}}
 return Array.isArray(a)?a.filter(x=>typeof x==="string"&&x.trim().length>0):[];
};
const getCatalog=async()=>{
 const rows=await sql.unsafe('SELECT id,species_kind AS type,scientific,common,family,alternative_names AS "alternativeNames",subgroup AS "group" FROM species_catalog ORDER BY species_kind,COALESCE(common,scientific)');
 return rows.map(s=>{
  const names=parseAliases(s.alternativeNames);
  return {...s,alternativeNames:s.type==="Snake"?names.map(safeSnakeName).filter(Boolean):names,common:s.type==="Snake"?safeSnakeName(s.common&&/[’']s$/.test(s.common)&&s.group?s.common+" "+s.group:s.common):s.common};
 });
};
const stableId=(kind,sci)=>createHash("sha1").update(kind+"|"+sci.toLowerCase()).digest("hex").slice(0,18);
const make=(kind,sci,common,family,alternatives=[],group="")=>({id:stableId(kind,sci),type:kind,scientific:sci,common:common||null,family:family||"",alternativeNames:alternatives,group});
const splitNames=s=>String(s||"").split(/[;|,\n]+/).map(x=>x.trim()).filter(x=>x&&x!=="NA"&&x!=="N/A");
const BIRDS_URL="https://indianbirds.in/wp-content/uploads/2026/05/India-Checklist_v10_1.xlsx";
const MAMMALS_URL="https://zenodo.org/records/21654811/files/MDD_v2.5_6904species.csv?download=1";
const REPTILES_URL="https://www.reptile-database.org/data/reptile_checklist_2026_06.xlsx";
const SNAKES_URL="https://reptile-database.reptarium.cz/advanced_search?exact%5B0%5D=location&location=India&submit=Search&taxon=snake";
async function source(u){const r=await fetch(u,{headers:{"user-agent":"PraaniSpeciesImporter/1.0"},signal:AbortSignal.timeout(75000)});if(!r.ok)throw Error("Official source HTTP "+r.status+" at "+u);return r}
async function workbook(u){const bytes=new Uint8Array(await(await source(u)).arrayBuffer());return XLSX.read(bytes,{type:"array"})}
async function importBirds(){const b=await workbook(BIRDS_URL);const sheet=b.Sheets["India_Checklist_10_1"];if(!sheet)throw Error("Birds v10.1 worksheet missing");const rows=XLSX.utils.sheet_to_json(sheet,{defval:""});const result=rows.filter(x=>x["Scientific Name"]&&!String(x.Vagrant||"").trim()&&!String(x.Historical||"").trim()).map(x=>make("Bird",String(x["Scientific Name"]).trim(),String(x["English Name"]).trim(),String(x.Family).trim(),splitNames(x["Alternative Names"])));if(result.length!==1211)throw Error("Bird count audit failed: "+result.length);return result}
async function importMammals(){const contents=await(await source(MAMMALS_URL)).text();const rows=parseCSV(contents,{columns:true,skip_empty_lines:true,relax_quotes:true});const result=rows.filter(x=>x.extinct==="0"&&x.domestic==="0"&&String(x.countryDistribution||"").split("|").some(s=>s==="India"||s==="Andaman and Nicobar Islands")).map(x=>make("Mammal",String(x.sciName).replaceAll("_"," ").trim(),x.mainCommonName==="NA"?"":x.mainCommonName,x.family,splitNames(x.otherCommonNames)));if(result.length!==445)throw Error("Mammal count audit failed: "+result.length);return result}
function snakeGroup(sci,fam){const g=sci.split(" ")[0].toLowerCase(),f=fam.toLowerCase();const byGenus={lycodon:"Wolf snake",hebius:"Keelback",fowlea:"Keelback",amphiesma:"Keelback",rhabdophis:"Keelback",trimeresurus:"Pit viper",craspedocephalus:"Pit viper",protobothrops:"Pit viper",gloydius:"Pit viper",bungarus:"Krait",naja:"Cobra",ophiophagus:"Cobra",dendrelaphis:"Bronzeback",ahaetulla:"Vine snake",boiga:"Cat snake",chrysopelea:"Flying snake",echis:"Viper",daboia:"Viper",eryx:"Sand boa",python:"Python",oligodon:"Kukri snake",xylophis:"Wood snake"};if(byGenus[g])return byGenus[g];if(f.includes("uropelt"))return "Shieldtail";if(f.includes("typhlop")||f.includes("gerrhopil"))return "Blind snake";if(f.includes("viper"))return "Viper";if(f.includes("elapid"))return "Elapid snake";if(f.includes("python"))return "Python";if(f.includes("boid")||f.includes("erycid"))return "Boa";if(f.includes("natric"))return "Keelback";if(f.includes("colubrid"))return "Colubrid snake";return fam||"Snake"}
async function snakeDetail(sci){const parts=sci.split(" ");const url="https://reptile-database.reptarium.cz/"+parts.join("/");let raw;for(let tries=0;tries<3;tries++){try{raw=await(await source(url)).text();break}catch(e){if(tries===2)throw e;await Bun.sleep((tries+1)*1100)}}const text=load(raw)("body").text().replace(/\s+/g," ");const i=text.indexOf("Common Names");const section=i>=0?text.slice(i+12).split(/\b(?:Synonym|Distribution|Etymology|References|Type locality|Reproduction)\b/i)[0]:"";const m=section.match(/(?:^|\s)E:\s*(.*?)(?=\s[A-Z][A-Za-z]{0,18}:|$)/);const names=m?splitNames(m[1]):[];const family=text.match(/Higher Taxa\s*([A-Z][a-zA-Z]+idae)\b/)?.[1]||"";return {common:safeSnakeName(names[0]),alternatives:names.slice(1).map(safeSnakeName).filter(Boolean),family}}
async function importSnakes(){const [html,wb]=await Promise.all([(await source(SNAKES_URL)).text(),workbook(REPTILES_URL)]);const $=load(html);const declared=Number(($("body").text().match(/Species found:\s*(\d+)/)||[])[1]);if(declared<340||declared>420)throw Error("Snake count unreasonable: "+declared);const names=$("h2").filter((i,e)=>$(e).text().trim()==="Search results").nextAll("ul").first().find("li a em").map((i,e)=>$(e).text().trim()).get();if(names.length!==declared||new Set(names).size!==declared)throw Error("Snake listing mismatch: "+names.length+" vs "+declared);const sheet=wb.Sheets.Checklist;if(!sheet)throw Error("2026 global reptile worksheet missing");const rows=XLSX.utils.sheet_to_json(sheet,{defval:""});const families=new Map(rows.filter(x=>x.order==="Serpentes").map(x=>[String(x.Species||"").trim(),String(x.Family||"").trim()]));const records=Array(names.length);let offset=0;await Promise.all(Array.from({length:3},async()=>{while(offset<names.length){const i=offset++,sci=names[i];const d=await snakeDetail(sci);const family=families.get(sci)||d.family;if(!family)throw Error("No verified family for snake "+sci);records[i]=make("Snake",sci,d.common,family,d.alternatives,snakeGroup(sci,family));await Bun.sleep(230)}}));if(records.length!==declared||records.some(x=>!x))throw Error("Incomplete snake audit");return records}
async function saveBatch(items){await sql.begin(async t=>{for(const x of items){await t.unsafe("INSERT INTO species_catalog(id,species_kind,scientific,common,family,alternative_names,subgroup) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(id) DO UPDATE SET scientific=excluded.scientific,common=excluded.common,family=excluded.family,alternative_names=excluded.alternative_names,subgroup=excluded.subgroup",[x.id,x.type,x.scientific,x.common,x.family,JSON.stringify(x.alternativeNames),x.group||""])}})}
let syncing=false,doneSync=false;
async function automaticSpeciesSync(){if(syncing||doneSync)return;syncing=true;try{const existing=await sql.unsafe("SELECT species_kind,COUNT(*)::int AS n FROM species_catalog GROUP BY species_kind");const map=Object.fromEntries(existing.map(x=>[x.species_kind,x.n]));for(const [name,expected,fn] of [["Bird",1211,importBirds],["Mammal",445,importMammals],["Snake",373,importSnakes]]){if(map[name]>=expected)continue;try{console.log("Praani importing official "+name+" species");const rows=await fn();if(new Set(rows.map(x=>x.id)).size!==rows.length)throw Error("Duplicate species IDs");for(let j=0;j<rows.length;j+=80)await saveBatch(rows.slice(j,j+80));console.log("Praani verified "+rows.length+" "+name+" records imported")}catch(e){console.error("Praani "+name+" source import failed:",String(e))}}doneSync=true}catch(e){console.error("Praani catalogue sync failed:",String(e))}finally{syncing=false}}
const startSpeciesSync=()=>{if(!syncing&&!doneSync)void automaticSpeciesSync()};
async function contribute(r){validateOrigin(r);const b=await body(r);const sp=clean(b.speciesId,48),kind=clean(b.type,20),name=clean(b.localName),language=clean(b.language,40),region=clean(b.region,90),proposal=clean(b.commonName),why=clean(b.why,480);const learnedFrom=clean(b.learnedFrom,100),context=clean(b.context,480);const allowedSources=['Used in my family or community','Heard from a local speaker','Used by local wildlife observers','Found in a book or online source','Other first-hand knowledge'];if(learnedFrom&&!allowedSources.includes(learnedFrom))throw new Err('Choose how you learned this name');if(!kinds.includes(kind)||!langs.includes(language))throw new Err("Select a species and language");if(!name&&!proposal)throw new Err("Add a local name or suggest a common name");if(name&&name.length<2)throw new Err("Local names need at least two characters");if(proposal&&proposal.length<2)throw new Err("Suggested names need at least two characters");if(proposal&&why.length<8)throw new Err("Explain the suggested name in eight or more characters");if(why&&!proposal)throw new Err("Enter the suggested name");const rows=await sql.unsafe("SELECT species_kind,common FROM species_catalog WHERE id=$1",[sp]);if(!rows.length||rows[0].species_kind!==kind)throw new Err("Species not in verified catalogue");const nk=norm(name),rk=norm(region),pk=norm(proposal);if(name&&(await sql.unsafe("SELECT 1 FROM local_names WHERE species_id=$1 AND name_key=$2 AND language=$3 AND region_key=$4",[sp,nk,language,rk])).length)throw new Err("Exact duplicate already recorded",409);if(proposal&&(await sql.unsafe("SELECT 1 FROM common_suggestions WHERE species_id=$1 AND name_key=$2",[sp,pk])).length)throw new Err("This suggested common name already exists",409);await throttle(r,"contribute",5,600);await sql.begin(async t=>{if(name){const id=randomUUID();await t.unsafe("INSERT INTO local_names(id,species_id,species_kind,name,name_key,language,region,region_key,created_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)",[id,sp,kind,name,nk,language,region,rk,now()]);if(learnedFrom)await t.unsafe("INSERT INTO local_name_context(local_name_id,learned_from,context) VALUES($1,$2,$3)",[id,learnedFrom,context]);}if(proposal)await t.unsafe("INSERT INTO common_suggestions(id,species_id,species_kind,name,name_key,why,language,region,created_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)",[randomUUID(),sp,kind,proposal,pk,why,language,region,now()])});return response({ok:true},201)}
async function vote(r){validateOrigin(r);const b=await body(r);const id=clean(b.suggestionId,50),token=clean(b.browserId,100);if(!/^[a-f0-9-]{36}$/.test(id)||!/^[a-zA-Z0-9_-]{20,90}$/.test(token))throw new Err("Invalid vote");if(!(await sql.unsafe("SELECT 1 FROM common_suggestions WHERE id=$1",[id])).length)throw new Err("Suggestion no longer exists",404);const hash=sha(token+"|"+env.SESSION_SECRET);if((await sql.unsafe("SELECT 1 FROM votes WHERE suggestion_id=$1 AND browser_hash=$2",[id,hash])).length)throw new Err("Already voted from this browser",409);await throttle(r,"vote",30,3600);try{await sql.unsafe("INSERT INTO votes(suggestion_id,browser_hash,created_at) VALUES($1,$2,$3)",[id,hash,now()])}catch(e){if(e.code==="23505")throw new Err("Already voted from this browser",409);throw e}const rows=await sql.unsafe("SELECT COUNT(*)::int AS n FROM votes WHERE suggestion_id=$1",[id]);return response({ok:true,votes:rows[0].n})}
async function entries(url){const f=url.searchParams.get("filter")||"All",language=url.searchParams.get("language")||"";if(!["All","Birds","Mammals","Snakes","Suggested names"].includes(f)||(language&&!langs.includes(language)))throw new Err("Invalid filter");const kind=({Birds:"Bird",Mammals:"Mammal",Snakes:"Snake"})[f]||"",only=f==="Suggested names",p=Math.min(250,Math.max(0,Math.floor(Number(url.searchParams.get("page"))||0)));const hits=await sql.unsafe("WITH combined AS (SELECT species_id,created_at FROM local_names WHERE ($1='' OR species_kind=$1) AND ($2='' OR language=$2) AND $3=FALSE UNION ALL SELECT species_id,created_at FROM common_suggestions WHERE ($1='' OR species_kind=$1) AND ($2='' OR language=$2)) SELECT species_id,MAX(created_at) AS recent FROM combined GROUP BY species_id ORDER BY recent DESC,species_id ASC LIMIT 21 OFFSET $4",[kind,language,only,p*20]);const ids=hits.slice(0,20).map(x=>x.species_id);if(!ids.length)return response({cards:[],hasMore:false});const [loc,sug]=await Promise.all([sql.unsafe("SELECT l.id,l.species_id,l.name,l.language,l.region,(SELECT c.learned_from FROM local_name_context c WHERE c.local_name_id=l.id) AS \"learnedFrom\",(SELECT c.context FROM local_name_context c WHERE c.local_name_id=l.id) AS context,COALESCE((SELECT jsonb_agg(jsonb_build_object('name',s.source_name,'url',s.source_url,'locator',s.source_locator) ORDER BY s.source_key) FROM local_name_sources s WHERE s.local_name_id=l.id),'[]'::jsonb) AS sources FROM local_names l WHERE l.species_id = ANY($1::text[]) AND ($2='' OR l.language=$2) ORDER BY l.created_at DESC",[ids,language]),sql.unsafe("SELECT s.id,s.species_id,s.name,s.why,s.language,s.region,COUNT(v.suggestion_id)::int AS votes FROM common_suggestions s LEFT JOIN votes v ON v.suggestion_id=s.id WHERE s.species_id = ANY($1::text[]) AND ($2='' OR s.language=$2) GROUP BY s.id ORDER BY votes DESC,s.created_at",[ids,language])]);return response({cards:ids.map(speciesId=>({speciesId,localNames:loc.filter(x=>x.species_id===speciesId),suggestions:sug.filter(x=>x.species_id===speciesId)})),hasMore:hits.length>20})}
async function missions(url){const language=url.searchParams.get('language')||'Kannada';if(!langs.includes(language))throw new Err('Choose a supported language');const gaps=await sql.unsafe('SELECT s.id FROM species_catalog s WHERE NOT EXISTS (SELECT 1 FROM local_names n WHERE n.species_id=s.id AND n.language=$1)',[language]);const missing=new Set(gaps.map(x=>x.id));const preferred=['Ratufa indica','Anthracoceros coronatus','Manis crassicaudata','Daboia russelii','Prionailurus viverrinus','Naja naja'];const remaining=(await getCatalog()).filter(s=>missing.has(s.id)&&s.common);const rank=s=>{const n=preferred.indexOf(s.scientific);return n<0?100:n};remaining.sort((a,b)=>rank(a)-rank(b)||a.common.localeCompare(b.common));return response({language,scope:'Praani records only',missions:kinds.map(type=>remaining.find(s=>s.type===type)).filter(Boolean)})}
async function admin(r,url){const path=url.pathname;if(path==="/api/admin/login"){validateOrigin(r);const b=await body(r);await throttle(r,"login",8,900);const value=sha(clean(b.email,200).toLowerCase()+"\n"+String(b.password||"")),expect=sha(String(env.ADMIN_EMAIL||"").toLowerCase()+"\n"+String(env.ADMIN_PASSWORD||""));if(!env.ADMIN_EMAIL||!env.ADMIN_PASSWORD||!env.SESSION_SECRET||!timingSafeEqual(Buffer.from(value),Buffer.from(expect)))throw new Err("Incorrect credentials",401);const exp=String(now()+86400);return response({ok:true},200,{"set-cookie":"praani_admin="+exp+"."+hmac(exp+"|"+env.ADMIN_EMAIL)+"; Max-Age=86400; Path=/; HttpOnly; Secure; SameSite=Strict"})}if(path==="/api/admin/status")return response({signedIn:authed(r)});if(path==="/api/admin/logout"){validateOrigin(r);return response({ok:true},200,{"set-cookie":"praani_admin=; Max-Age=0; Path=/; HttpOnly; Secure; SameSite=Strict"})}if(!authed(r))throw new Err("Administrator login required",401);if(path==="/api/admin/entries"){const [a,b]=await Promise.all([sql.unsafe("SELECT id,species_id,species_kind,name,language,region FROM local_names ORDER BY created_at DESC LIMIT 300"),sql.unsafe("SELECT id,species_id,species_kind,name,why,language,region FROM common_suggestions ORDER BY created_at DESC LIMIT 300")]);return response({localNames:a,suggestions:b})}if(path==="/api/admin/delete"){validateOrigin(r);const b=await body(r);const id=clean(b.id,40),type=clean(b.kind,20);if(!/^[0-9a-f-]{36}$/.test(id)||!["local","suggestion"].includes(type))throw new Err("Invalid deletion");const table=type==="local"?"local_names":"common_suggestions";const result=await sql.unsafe("DELETE FROM "+table+" WHERE id=$1",[id]);return response({ok:true,deleted:result.count})}throw new Err("Not found",404)}
