const ADMIN_HTML=String.raw`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/style.css?v=allnamesv1520261022"><title>Praani — private steward page</title><style>.desk{max-width:840px;margin:65px auto 100px;padding:0 22px}.desk h1{font-size:46px}.sign{max-width:460px;padding:25px;border:1px solid var(--line);background:var(--card);border-radius:10px}.sign input{width:100%;display:block;margin:8px 0 20px;border:1px solid var(--line);border-radius:5px;padding:13px;color:var(--ink);background:var(--bg)}.admin-item{display:flex;align-items:center;justify-content:space-between;gap:15px;background:var(--card);border:1px solid var(--line);padding:15px;margin:9px 0;border-radius:7px}.admin-item small{display:block;color:var(--muted);margin-top:7px}.admin-item button{color:var(--ink);border:1px solid var(--line);background:transparent;padding:9px}.desk h2{font-size:30px}.desk p{color:var(--muted)}</style></head><body><header class="header wrap"><a href="/" class="logo">praani<span class="dot">.</span></a><span class="eyebrow">PRIVATE ADMINISTRATOR</span></header><main class="desk"><div class="eyebrow">ARCHIVE STEWARD</div><h1>Review the archive.</h1><p id="status" aria-live="polite"></p><form id="login" class="sign" hidden><label for="email">Email</label><input id="email" type="email" autocomplete="username" required><label for="pass">Password</label><input id="pass" type="password" autocomplete="current-password" required><button class="primary">Sign in</button></form><section id="work" hidden><button id="logout" class="primary">Sign out</button><h2>Local names</h2><div id="local"></div><h2>Common-name suggestions</h2><div id="suggestions"></div></section></main><script defer src="/admin.js?v=20261022"></script></body></html>`;
const ADMIN_JS=String.raw`(()=>{const $=x=>document.querySelector(x);const say=x=>$('#status').textContent=x;const make=(tag,parent,str)=>{const e=document.createElement(tag);e.textContent=str;parent.appendChild(e);return e};async function api(path,opts){const r=await fetch('/api/admin/'+path,{credentials:'same-origin',cache:'no-store',...opts});const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v}async function init(){try{const s=await api('status');$('#login').hidden=s.signedIn;$('#work').hidden=!s.signedIn;if(s.signedIn)await load()}catch(e){say(e.message);$('#login').hidden=false}}async function load(){const d=await api('entries');for(const [list,root,kind] of [[d.localNames,'#local','local'],[d.suggestions,'#suggestions','suggestion']]){$(root).replaceChildren();for(const x of list){const item=make('div',$(root),'');item.className='admin-item';const left=make('div',item,'');make('strong',left,x.name);make('small',left,[x.species_kind,x.language,x.region,x.species_id].filter(Boolean).join(' · '));if(x.why)make('small',left,'Reason: '+x.why);const b=make('button',item,'Delete');b.onclick=async()=>{if(!confirm('Permanently delete “'+x.name+'”?'))return;try{await api('delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:x.id,kind})});item.remove();say('Deleted.')}catch(e){say(e.message)}}}}}$('#login').onsubmit=async e=>{e.preventDefault();try{await api('login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:$('#email').value,password:$('#pass').value})});$('#pass').value='';say('Signed in');init()}catch(e){say(e.message)}};$('#logout').onclick=async()=>{await api('logout',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});init()};init()})();`;
const decodeStaticUnicode=text=>text.replace(new RegExp("(?:"+String.fromCharCode(92,92)+")+u([0-9a-fA-F]{4})","g"),(_,hex)=>String.fromCharCode(parseInt(hex,16)));
Bun.serve({port:Number(env.PORT||3000),hostname:"0.0.0.0",fetch:async r=>{const url=new URL(r.url),path=url.pathname;try{
if(path==="/style.css")return page(decodeStaticUnicode(CSS),"text/css; charset=utf-8");
if(path==="/app.js")return page(decodeStaticUnicode(CLIENT),"application/javascript; charset=utf-8");
if(path==="/admin.js")return page(decodeStaticUnicode(ADMIN_JS),"application/javascript; charset=utf-8");
if(path==="/favicon.ico")return new Response(null,{status:204});
if(path==="/"||path==="/index.html"){let species=[];try{await ready();species=await getCatalog()}catch(e){console.error("catalogue read failure",e)}startSpeciesSync();const json=JSON.stringify(species).replace(/</g,"\\u003c").replace(/>/g,"\\u003e").replace(/&/g,"\\u0026");const escapeOption=x=>String(x||"").replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;");return page(decodeStaticUnicode(HTML).replace("__PRAANI_SPECIES_JSON__",json))}
if(path==="/admin"||path==="/admin/")return page(decodeStaticUnicode(ADMIN_HTML));
if(!path.startsWith("/api/"))return new Response("Not found",{status:404});
await ready();
if(path==="/api/health"){const rows=await sql.unsafe("SELECT COUNT(*)::int AS total FROM species_catalog");return response({ok:true,release:RELEASE,database:"connected",species:rows[0].total,namesImport})}
if(r.method==="GET"&&path==="/api/catalog-status"){startSpeciesSync();const rows=await sql.unsafe("SELECT COUNT(*)::int AS total FROM species_catalog");return response({total:rows[0].total})}
if(r.method==="GET"&&path==="/api/missions")return await missions(url);
if(r.method==="GET"&&path==="/api/entries")return await entries(url);
if(r.method==="POST"&&path==="/api/contribute")return await contribute(r);
if(r.method==="POST"&&path==="/api/vote")return await vote(r);
if(path.startsWith("/api/admin/"))return await admin(r,url);
return response({error:"Not found"},404)
}catch(e){console.error(e);const duplicate=e?.code==="23505";return response({error:duplicate?"Exact duplicate already recorded":e instanceof Err?e.message:"Service temporarily unavailable"},duplicate?409:e instanceof Err?e.status:500)} }});

